"use strict";
import { useQuery } from "@tanstack/react-query";
import { useMemo } from "react";
import { ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
import { Contract } from "@ethersproject/contracts";
import { BigNumber } from "@ethersproject/bignumber";
import { useAccount } from "hooks/useAccount";
import { useEthersProvider } from "hooks/useEthersProvider";
import { fetchAbstractV3CollectableFees } from "hooks/utils/fetchAbstractV3Fees";
import NonfungiblePositionManagerJson from "@uniswap/v3-periphery/artifacts/contracts/NonfungiblePositionManager.sol/NonfungiblePositionManager.json";
import { useGaugesData } from "hooks/useGaugeData";
import { fetchOnChainPositions } from "features/liquidity/onChainPositions/fetchOnChainPositions";
import { getAbstractContracts } from "uniswap/src/constants/abstractContracts";
const V2_BALANCE_ABI = ["function balanceOf(address) view returns (uint256)"];
const { abi: NON_FUNGIBLE_POSITION_MANAGER_ABI } = NonfungiblePositionManagerJson;
async function enrichPositionWithOnChainData({
  position,
  provider,
  chainId,
  userAddress
}) {
  if (!provider || !userAddress) {
    return position;
  }
  const contracts = getAbstractContracts(chainId);
  const normalizedUser = userAddress.toLowerCase();
  const updated = { ...position };
  try {
    if (updated.version === ProtocolVersion.V3 && updated.tokenId && contracts?.nonfungiblePositionManager) {
      try {
        const nftContract = new Contract(
          contracts.nonfungiblePositionManager,
          NON_FUNGIBLE_POSITION_MANAGER_ABI,
          provider
        );
        const owner = await nftContract.ownerOf(updated.tokenId);
        const gaugeAddressLower = updated.gaugeAddress?.toLowerCase();
        const isStaked = gaugeAddressLower ? owner?.toLowerCase?.() === gaugeAddressLower : false;
        updated.hasGaugeStake = Boolean(updated.gaugeAddress);
        updated.isStaked = isStaked;
        updated.isGaugePosition = Boolean(updated.gaugeAddress);
        updated.isPartiallyStaked = false;
      } catch (error) {
        console.warn("[POSITION] Failed to fetch V3 owner on-chain", {
          tokenId: updated.tokenId,
          error
        });
      }
    }
    if (updated.version === ProtocolVersion.V2 && updated.poolId && updated.gaugeAddress) {
      try {
        const poolContract = new Contract(updated.poolId, V2_BALANCE_ABI, provider);
        const gaugeContract = new Contract(updated.gaugeAddress, V2_BALANCE_ABI, provider);
        const [walletBalanceRaw, gaugeBalanceRaw] = await Promise.all([
          poolContract.balanceOf(normalizedUser),
          gaugeContract.balanceOf(normalizedUser)
        ]);
        const walletBalance = BigNumber.from(walletBalanceRaw ?? 0);
        const gaugeBalance = BigNumber.from(gaugeBalanceRaw ?? 0);
        const totalBalance = walletBalance.add(gaugeBalance);
        const hasGaugeStake = gaugeBalance.gt(0);
        const isStaked = hasGaugeStake && walletBalance.isZero();
        const isPartiallyStaked = hasGaugeStake && walletBalance.gt(0);
        const stakingPercentage = hasGaugeStake && totalBalance.gt(0) ? Number(gaugeBalance.mul(1e4).div(totalBalance).toString()) / 100 : 0;
        updated.hasGaugeStake = hasGaugeStake;
        updated.isStaked = isStaked;
        updated.isPartiallyStaked = isPartiallyStaked;
        updated.stakedAmount = gaugeBalance.toString();
        updated.unstakedAmount = walletBalance.toString();
        updated.stakingPercentage = stakingPercentage;
      } catch (error) {
        console.warn("[POSITION] Failed to fetch V2 staking balances on-chain", {
          pool: updated.poolId,
          gauge: updated.gaugeAddress,
          error
        });
      }
    }
  } catch (error) {
    console.warn("[POSITION] Unexpected error applying on-chain status", error);
  }
  return updated;
}
export function useAbstractPosition(tokenId, chainId) {
  const account = useAccount();
  const provider = useEthersProvider({ chainId });
  const { data: gaugeData, isLoading: isGaugeLoading } = useGaugesData(chainId);
  const gaugeMappings = useMemo(() => {
    if (!gaugeData?.poolMappings?.length) {
      return [];
    }
    const gaugeStatusById = /* @__PURE__ */ new Map();
    gaugeData.gauges?.forEach((gauge) => {
      gaugeStatusById.set(gauge.id.toLowerCase(), { isAlive: gauge?.isAlive ?? true });
    });
    return gaugeData.poolMappings.filter((mapping) => Boolean(mapping.gauge)).map((mapping) => {
      const status = gaugeStatusById.get(mapping.gauge.toLowerCase());
      return {
        poolAddress: mapping.pool,
        gaugeAddress: mapping.gauge,
        isAlive: status?.isAlive ?? true
      };
    });
  }, [gaugeData?.poolMappings, gaugeData?.gauges]);
  return useQuery({
    queryKey: ["abstract-position", tokenId, chainId, account.address, Boolean(provider), gaugeMappings.length],
    queryFn: async () => {
      if (!tokenId || !account.address || !provider) {
        return null;
      }
      try {
        const { positions } = await fetchOnChainPositions({
          userAddress: account.address,
          chainId,
          provider,
          gauges: gaugeMappings
        });
        let positionInfo = positions.find((position) => {
          if (position.version === ProtocolVersion.V3) {
            return position.tokenId?.toString() === tokenId;
          }
          return false;
        });
        if (!positionInfo) {
          return null;
        }
        if (positionInfo.version === ProtocolVersion.V3) {
          const feeUpdate = await fetchAbstractV3CollectableFees({
            provider,
            chainId,
            tokenId: positionInfo.tokenId,
            ownerAddress: positionInfo.owner,
            recipientAddress: account.address,
            gaugeAddress: positionInfo.gaugeAddress
          });
          if (feeUpdate) {
            positionInfo = {
              ...positionInfo,
              token0UncollectedFees: feeUpdate.amount0,
              token1UncollectedFees: feeUpdate.amount1
            };
          }
        }
        positionInfo = await enrichPositionWithOnChainData({
          position: positionInfo,
          provider,
          chainId,
          userAddress: account.address
        });
        return {
          ...positionInfo,
          isHidden: false
        };
      } catch (error) {
        console.error(`\u274C [POSITION] Error fetching position ${tokenId}:`, error);
        return null;
      }
    },
    enabled: !!tokenId && !!account.address && !isGaugeLoading,
    refetchInterval: 3e4
    // Refetch every 30 seconds
  });
}
